import{c as a,Q as t,j as s,m as n}from"./chunks/framework.g_l1frA7.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"developers/architecture.md","filePath":"developers/architecture.md","lastUpdated":null}'),i={name:"developers/architecture.md"};function r(d,e,o,p,c,l){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>FinSight is a single server binary serving an SPA over same-origin HTTP/SSE. No Tauri binary remains — <code>finsight-server</code> is the product.</p><h2 id="high-level" tabindex="-1">High-level <a class="header-anchor" href="#high-level" aria-label="Permalink to &quot;High-level&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Browser / PWA</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span> HTTP RPC + CSV upload + SSE (+ GET /api/openapi.json)</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span> crates/finsight-server  (Axum, serves ui/dist)</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span> crates/finsight-api  (transport-agnostic handlers + ApiState)</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span> ┌────────────┼──────────────┐</span></span>
<span class="line"><span> finsight-core  finsight-agent  finsight-providers</span></span></code></pre></div><h2 id="crates" tabindex="-1">Crates <a class="header-anchor" href="#crates" aria-label="Permalink to &quot;Crates&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Crate</th><th>Role</th><th>Depends on Tauri?</th></tr></thead><tbody><tr><td><code>finsight-core</code></td><td>Domain: models, SQLCipher pool (r2d2), migrations (Refinery), repos, metrics/forecast/cashflow, settings KV</td><td>No</td></tr><tr><td><code>finsight-providers</code></td><td>CSV parsers, LLM providers (<code>CompletionProvider</code> with Ollama / OpenAI-compat / Anthropic)</td><td>No</td></tr><tr><td><code>finsight-agent</code></td><td>Copilot context (<code>build_context</code>), planner, executor, recipe runner, categorizer, anomalies</td><td>No</td></tr><tr><td><code>finsight-api</code></td><td>Transport-agnostic command bodies + <code>ApiState</code></td><td>No</td></tr><tr><td><code>finsight-openapi</code></td><td>Typed OpenAPI spec (utoipa) — <code>COMMANDS</code> + <code>build_openapi()</code></td><td>No</td></tr><tr><td><code>finsight-server</code></td><td>Axum auth/RPC/uploads/SSE/static UI/user runtimes</td><td>No</td></tr><tr><td><code>finsight-eval</code></td><td>Evaluation fixtures &amp; runners</td><td>—</td></tr></tbody></table><h2 id="data-layout" tabindex="-1">Data layout <a class="header-anchor" href="#data-layout" aria-label="Permalink to &quot;Data layout&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data                  # Docker volume; dev ./data</span></span>
<span class="line"><span>├── users.db            # registry: usernames, Argon2id verifiers, wrapped keys, hashed sessions</span></span>
<span class="line"><span>├── session.key         # wraps persisted sessions</span></span>
<span class="line"><span>└── users/&lt;uuid&gt;/</span></span>
<span class="line"><span>    ├── data.sqlcipher   # per-user encrypted ledger</span></span>
<span class="line"><span>    ├── backups/</span></span>
<span class="line"><span>    └── imports/</span></span></code></pre></div><p>Per-user runtimes are lazy, single-flighted, and evicted after 30 minutes idle (unless SSE attached). Sessions have a sliding 30-day lifetime and survive restarts.</p><h2 id="transport" tabindex="-1">Transport <a class="header-anchor" href="#transport" aria-label="Permalink to &quot;Transport&quot;">​</a></h2><ul><li><code>POST /api/rpc/{cmd}</code> — typed RPC, envelope <code>Result&lt;T,AppError&gt;</code>, camelCase args via <code>arg(&amp;p, &quot;camelCase&quot;)</code></li><li><code>GET /api/events</code> — SSE for Copilot streaming and invalidations</li><li><code>GET /api/openapi.json</code> — generated spec at runtime</li><li><code>ui/dist</code> — served by <code>finsight-server</code> at <code>/</code> (SPA fallback)</li></ul><p>All DB access is through repos in <code>finsight-core</code>, not inline SQL in handlers.</p><p>Next: <a href="/FinSight/developers/setup">Development Setup</a>.</p>`,13)])])}const g=a(i,[["render",r]]);export{u as __pageData,g as default};
